import{_ as e,o,c as d,a2 as a}from"./chunks/framework.il0noOp3.js";const m=JSON.parse('{"title":"Report conformance — the quality bar","description":"","frontmatter":{},"headers":[],"relativePath":"design/report-conformance.md","filePath":"design/report-conformance.md"}'),r={name:"design/report-conformance.md"};function n(s,t,c,i,h,l){return o(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="report-conformance-—-the-quality-bar" tabindex="-1">Report conformance — the quality bar <a class="header-anchor" href="#report-conformance-—-the-quality-bar" aria-label="Permalink to &quot;Report conformance — the quality bar&quot;">​</a></h1><p><strong>Status:</strong> normative. This document is the <strong>definition of done</strong> for every item under Epic AB#6450. <strong>Work item:</strong> Feature AB#6887; the test is Story AB#6888. <strong>Enforced by:</strong> <code>tests/Report.Conformance.Tests.ps1</code> — written, and green on the clauses below marked <code>automatic</code> except where a row says otherwise. It emits a package from a synthetic fixture and reads the OpenXML / project files back off disk, so a renderer cannot pass a clause by claiming to satisfy it. <strong>Derived from:</strong> <code>pmo/research/R4-reference-deliverable-teardown.md</code> in the repository. Not linked: <code>/pmo</code> holds internal programme records and is deliberately not published to this site, so a relative link out of <code>docs/</code> is a dead link at build time.</p><hr><h2 id="why-this-exists" tabindex="-1">Why this exists <a class="header-anchor" href="#why-this-exists" aria-label="Permalink to &quot;Why this exists&quot;">​</a></h2><p>103 report work items on this board are Closed. <code>AB#5044</code> &quot;Rebuild reporting into a tiered renderer engine&quot;. <code>AB#333</code> Word. <code>AB#334</code> PDF. <code>AB#329</code> Power BI. <code>AB#6458</code> &quot;Build consultant-grade governance assessment report generator&quot; is marked Resolved.</p><p>Every one of them was accepted on <strong>&quot;a file came out.&quot;</strong> Not one had an acceptance criterion naming an example deliverable, a required section, or a reader. There had never been a quality bar on this project, so 103 tickets closed green while the output stayed unusable.</p><p><strong>A renderer work item may not be closed on the existence of a file.</strong> It closes when the clauses below that apply to it pass, and the conformance test is what says so.</p><hr><h2 id="how-to-read-this" tabindex="-1">How to read this <a class="header-anchor" href="#how-to-read-this" aria-label="Permalink to &quot;How to read this&quot;">​</a></h2><p>Each clause has an id, a statement, and a <strong>verification</strong> that is either <code>automatic</code> (asserted by the conformance test against an emitted package) or <code>judged</code> (needs a human reading the artefact next to the reference).</p><p><code>automatic</code> clauses are the ones worth arguing about, because they are the ones that cannot be closed by opinion. Most of them are properties of the <strong>package</strong>, so they need no tenant and no live data — the test emits a report from a fixture and reads the OpenXML back.</p><hr><h2 id="w-—-word-document" tabindex="-1">W — Word document <a class="header-anchor" href="#w-—-word-document" aria-label="Permalink to &quot;W — Word document&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Id</th><th>Clause</th><th>Verification</th></tr></thead><tbody><tr><td><code>W-01</code></td><td>The package contains a <code>StyleDefinitionsPart</code> declaring named styles for Title, Heading 1–3, Normal, Caption and a table style.</td><td>automatic</td></tr><tr><td><code>W-02</code></td><td>Every heading paragraph carries a <code>pStyle</code> referencing a declared style. No heading is formatted by direct run properties.</td><td>automatic</td></tr><tr><td><code>W-03</code></td><td>The package contains a header part, and it is referenced by the section properties.</td><td>automatic</td></tr><tr><td><code>W-04</code></td><td>The package contains a footer part containing a <code>PAGE</code> field.</td><td>automatic</td></tr><tr><td><code>W-05</code></td><td>The document contains a real TOC <strong>field</strong> (<code>TOC \\o</code>), not a list of paragraphs.</td><td>automatic</td></tr><tr><td><code>W-06</code></td><td>The package contains a numbering part, and chapter headings reference it.</td><td>automatic</td></tr><tr><td><code>W-07</code></td><td>The package contains a theme part. No run in the body hardcodes a hex colour that is absent from the theme.</td><td>automatic</td></tr><tr><td><code>W-08</code></td><td>The first page is a cover carrying: client/tenant name, assessment name, scan date, and classification.</td><td>automatic</td></tr><tr><td><code>W-09</code></td><td>A Document Information block follows the cover, carrying version, author, frameworks referenced, <strong>source data provenance and scan date</strong>.</td><td>automatic</td></tr><tr><td><code>W-10</code></td><td>An Executive Summary precedes the first finding chapter. Conclusion before detail.</td><td>automatic</td></tr><tr><td><code>W-11</code></td><td>Each assessment domain is emitted as a chapter with the shape: chapter-level scorecard table → Current State → findings table(s) → action items.</td><td>automatic</td></tr><tr><td><code>W-12</code></td><td>Every figure referenced in the body is an embedded image part. A figure that failed to render is omitted with a caption saying so — never a broken reference.</td><td>automatic</td></tr><tr><td><code>W-13</code></td><td>Long tables (&gt; 30 rows) are emitted to an appendix, not the body.</td><td>automatic</td></tr><tr><td><code>W-14</code></td><td>Every findings-table row carries its supporting number and at least one named resource.</td><td>judged</td></tr><tr><td><code>W-15</code></td><td>Passing controls appear alongside failures. An all-negative report is non-conformant.</td><td>judged</td></tr><tr><td><code>W-16</code></td><td>Narrative sentences are comparative or aggregate — properties of the whole run, not per-rule templates.</td><td>judged</td></tr><tr><td><code>W-17</code></td><td>Nothing that was not measured is asserted. &quot;Not assessed&quot; is a first-class state and is never rendered as a zero or a pass.</td><td>automatic</td></tr></tbody></table><h2 id="p-—-powerpoint-deck" tabindex="-1">P — PowerPoint deck <a class="header-anchor" href="#p-—-powerpoint-deck" aria-label="Permalink to &quot;P — PowerPoint deck&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Id</th><th>Clause</th><th>Verification</th></tr></thead><tbody><tr><td><code>P-01</code></td><td>The deck uses slide layouts from a master. No slide is built purely from free-floating shapes.</td><td>automatic</td></tr><tr><td><code>P-02</code></td><td>Slide 1 is a title slide carrying client/tenant, assessment name and date.</td><td>automatic</td></tr><tr><td><code>P-03</code></td><td>The deck contains a scope slide stating what was <strong>not</strong> assessed.</td><td>automatic</td></tr><tr><td><code>P-04</code></td><td>The deck contains exactly one &quot;act on this first&quot; slide naming a specific item.</td><td>automatic</td></tr><tr><td><code>P-05</code></td><td>Deck length is bounded — a roll-up deck is ≤ 15 slides. One idea per slide.</td><td>automatic</td></tr><tr><td><code>P-06</code></td><td>Scorecard tiles carry a band label, not a bare number.</td><td>judged</td></tr></tbody></table><h2 id="x-—-excel-workbook" tabindex="-1">X — Excel workbook <a class="header-anchor" href="#x-—-excel-workbook" aria-label="Permalink to &quot;X — Excel workbook&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Id</th><th>Clause</th><th>Verification</th></tr></thead><tbody><tr><td><code>X-01</code></td><td>Sheet 1 is a Cover carrying scope, a legend, and a contents index listing every other tab <strong>with its record count</strong>.</td><td>automatic</td></tr><tr><td><code>X-02</code></td><td>One tab per gap class, named for the gap, not for the collector.</td><td>automatic</td></tr><tr><td><code>X-03</code></td><td>Every data tab has frozen panes and an autofilter on the header row.</td><td>automatic</td></tr><tr><td><code>X-04</code></td><td>Every evidence row carries the full ARM resource id.</td><td>automatic</td></tr><tr><td><code>X-05</code></td><td>Every gap row carries a triage verdict (real / by-design / sandbox / legacy).</td><td>automatic</td></tr></tbody></table><h2 id="d-—-diagrams" tabindex="-1">D — Diagrams <a class="header-anchor" href="#d-—-diagrams" aria-label="Permalink to &quot;D — Diagrams&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Id</th><th>Clause</th><th>Verification</th></tr></thead><tbody><tr><td><code>D-01</code></td><td>Every generated diagram is rasterised to PNG alongside its source form.</td><td>automatic</td></tr><tr><td><code>D-02</code></td><td>A diagram that fails to render is reported as a warning and omitted — never emitted broken or empty.</td><td>automatic</td></tr><tr><td><code>D-03</code></td><td>Diagrams embedded in Word/PPTX/PDF are the rasterised output, not a link.</td><td>automatic</td></tr></tbody></table><h2 id="b-—-power-bi" tabindex="-1">B — Power BI <a class="header-anchor" href="#b-—-power-bi" aria-label="Permalink to &quot;B — Power BI&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Id</th><th>Clause</th><th>Verification</th></tr></thead><tbody><tr><td><code>B-01</code></td><td>The output is a PBIP project (semantic model + report, as text), not a <code>.pbit</code> over flat CSVs.</td><td>automatic</td></tr><tr><td><code>B-02</code></td><td>The model declares relationships between fact and dimension tables. A single text key is non-conformant.</td><td>automatic</td></tr><tr><td><code>B-03</code></td><td>The model declares DAX measures. A model with zero measures is non-conformant.</td><td>automatic</td></tr><tr><td><code>B-04</code></td><td>The model declares a date dimension.</td><td>automatic</td></tr><tr><td><code>B-05</code></td><td>The project contains <strong>authored report pages</strong>. Opening it must not present a blank canvas.</td><td>automatic</td></tr></tbody></table><h2 id="r-—-run-output-contract" tabindex="-1">R — Run output contract <a class="header-anchor" href="#r-—-run-output-contract" aria-label="Permalink to &quot;R — Run output contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Id</th><th>Clause</th><th>Verification</th></tr></thead><tbody><tr><td><code>R-01</code></td><td>A run that selects N assessments produces N per-assessment report sets, not one merged document.</td><td>automatic</td></tr><tr><td><code>R-02</code></td><td>Inventory output is emitted under <code>inventory/</code>, per-assessment output under <code>assessments/&lt;name&gt;/</code>.</td><td>automatic</td></tr><tr><td><code>R-03</code></td><td>A run of more than one assessment additionally produces a cross-assessment roll-up under <code>executive/</code>.</td><td>automatic</td></tr><tr><td><code>R-04</code></td><td>Every renderer consumes the same derived report model. No renderer re-derives findings.</td><td>automatic</td></tr></tbody></table><hr><h2 id="where-the-bar-stands-today" tabindex="-1">Where the bar stands today <a class="header-anchor" href="#where-the-bar-stands-today" aria-label="Permalink to &quot;Where the bar stands today&quot;">​</a></h2><p>Recorded honestly rather than optimistically, because a bar that reports itself as met is the failure this document exists to prevent.</p><table tabindex="0"><thead><tr><th>State</th><th>Clauses</th></tr></thead><tbody><tr><td><strong>Asserted and passing</strong></td><td><code>W-01</code>–<code>W-11</code>, <code>W-13</code>, <code>W-17</code>; <code>P-01</code>, <code>P-02</code>, <code>P-05</code>; <code>X-03</code>; <code>B-01</code>–<code>B-05</code>; <code>R-04</code></td></tr><tr><td><strong>Asserted elsewhere</strong></td><td><code>R-01</code>, <code>R-02</code> — <code>tests/Report.PerAssessmentContract.Tests.ps1</code></td></tr><tr><td><strong>Not yet asserted</strong></td><td><code>W-12</code>; <code>P-03</code>, <code>P-04</code>; <code>X-01</code>, <code>X-02</code>, <code>X-04</code>, <code>X-05</code>; <code>D-01</code>–<code>D-03</code>; <code>R-03</code></td></tr><tr><td><strong>Judged, never automatic</strong></td><td><code>W-14</code>, <code>W-15</code>, <code>W-16</code>, <code>P-06</code></td></tr></tbody></table><p>The <code>D</code> clauses are blocked on diagram rasterisation (<code>AB#6737</code>), and <code>W-12</code> is blocked behind them: a document cannot embed a figure the pipeline does not produce as an image. That dependency is the reason those four sit together.</p><p><strong>One thing the Power BI clauses cannot prove here.</strong> <code>B-01</code>–<code>B-05</code> are asserted against the emitted PBIP project&#39;s files — the TMDL parses as the shape it claims, the relationships name real columns, the report pages carry visuals whose configs deserialise. They do <strong>not</strong> prove Power BI Desktop opens it, because Desktop is not available on the CI runner or in the authoring environment. Opening the generated project in Desktop is an open verification step, not a closed one.</p><h2 id="scope-note-—-what-the-bar-does-not-cover" tabindex="-1">Scope note — what the bar does not cover <a class="header-anchor" href="#scope-note-—-what-the-bar-does-not-cover" aria-label="Permalink to &quot;Scope note — what the bar does not cover&quot;">​</a></h2><p>Report depth is capped by assessment depth. Scout has 395 rules, 225 of them <code>manual: true</code>, and rule authoring belongs to Epic AB#6454, not here. A conformant report that says &quot;not assessed&quot; for a manual control <strong>is conformant</strong> — clause <code>W-17</code> requires exactly that. This bar governs whether the artefact is fit to put in front of an executive, not whether the assessment behind it is deep.</p><hr><h2 id="changing-this-document" tabindex="-1">Changing this document <a class="header-anchor" href="#changing-this-document" aria-label="Permalink to &quot;Changing this document&quot;">​</a></h2><p>A clause may be removed or weakened only with a recorded reason on the epic. Adding a clause needs no ceremony. If a renderer cannot meet a clause, that is a finding about the renderer — the bar does not move to meet the implementation, because that is precisely the failure this document exists to prevent.</p>',35)])])}const p=e(r,[["render",n]]);export{m as __pageData,p as default};
